/** Hosted live Lab: status-driven current testing UI. */
export const uiHtml="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\"><meta name=\"color-scheme\" content=\"light\">\n<title>Product Insights by IJ AI · Live Testing</title><link rel=\"stylesheet\" href=\"/assets/style.css\"><script defer src=\"/assets/app.js\"></script></head>\n<body>\n<header class=\"top\">\n <div class=\"identity\"><span class=\"mark\" aria-hidden=\"true\">✦</span><span class=\"brand\"><strong>Product Insights by IJ AI</strong><small>Live company intelligence · Research prototype</small></span></div>\n <div class=\"top-actions\"><span class=\"prototype-tag\">LIVE TEST ENVIRONMENT</span><span id=\"connection\" class=\"pill offline\" aria-live=\"polite\">Laptop disconnected</span></div>\n</header>\n<div id=\"login\" class=\"loginwrap\"><section class=\"auth\">\n <span class=\"eyebrow\">PRIVATE TEAM ACCESS</span><h1>See what Product Insights discovers. Live.</h1>\n <p>Real website investigations run through the approved laptop. This application shows source-backed findings, AI suggestions, missing information and technical failures—not a template.</p>\n <form id=\"login-form\"><label for=\"team-key\">Team access key</label><input id=\"team-key\" type=\"password\" autocomplete=\"off\" placeholder=\"Enter the team key\" required><button type=\"submit\" class=\"primary\">Open live testing Lab</button></form>\n <p id=\"login-message\" class=\"error\" aria-live=\"polite\"></p><p class=\"fine\">The team key is used only in this browser session and is never put in the URL.</p>\n</section></div>\n<div id=\"app\" class=\"app-shell\" hidden>\n <aside class=\"sidebar\" aria-label=\"Lab navigation\">\n  <div class=\"sidebar-label\">WORKSPACE</div>\n  <button type=\"button\" id=\"nav-tests\" class=\"nav-item selected\"><span class=\"nav-icon\">◉</span>Live tests</button>\n  <button type=\"button\" id=\"nav-results\" class=\"nav-item\"><span class=\"nav-icon\">▣</span>Product insights</button>\n  <button type=\"button\" id=\"nav-taxonomy\" class=\"nav-item\"><span class=\"nav-icon\">◇</span>AI taxonomy</button>\n  <button type=\"button\" id=\"nav-technical\" class=\"nav-item\"><span class=\"nav-icon\">⌘</span>Technical view</button>\n  <div class=\"sidebar-divider\"></div>\n  <div class=\"sidebar-label\">HOW TO READ RESULTS</div>\n  <div class=\"sidebar-status\"><span class=\"legend-dot green\"></span><span><b>Extracted</b><small>Present in website evidence</small></span></div>\n  <div class=\"sidebar-status\"><span class=\"legend-dot amber\"></span><span><b>Needs review</b><small>AI proposal or unverified claim</small></span></div>\n  <div class=\"sidebar-status\"><span class=\"legend-dot red\"></span><span><b>Couldn't bring out</b><small>Not established by this test</small></span></div>\n  <div class=\"sidebar-note\"><strong>Manuel's view</strong><p>See what the system found, what AI proposed, and what it could not establish. Switch to Technical View for the details.</p></div>\n </aside>\n <main class=\"workspace\">\n  <div class=\"workspace-crumb\">Product Insights <span>/</span> Live investigation</div>\n  <section class=\"hero\"><div class=\"hero-row\"><div>\n   <span class=\"eyebrow\">REAL WEBSITE RESEARCH · NO SIMULATED RESULTS</span>\n   <h1>Company intelligence, as it happens.</h1>\n   <p>Run a real investigation. Every section shows its result and whether the finding is extracted, AI-inferred, or missing.</p>\n  </div><div class=\"view-tabs\" role=\"group\" aria-label=\"Display modes\">\n   <button id=\"mode-business\" type=\"button\" class=\"on\" aria-pressed=\"true\">Product Insights</button>\n   <button id=\"mode-technical\" type=\"button\" aria-pressed=\"false\">Technical View</button>\n  </div></div>\n  <div class=\"status-legend\"><strong>Result legend</strong>\n   <span><i class=\"legend-dot green\"></i><b>Green:</b> extracted with source</span>\n   <span><i class=\"legend-dot amber\"></i><b>Amber:</b> needs human review</span>\n   <span><i class=\"legend-dot red\"></i><b>Red:</b> couldn't bring this out</span>\n  </div></section>\n  <div class=\"columns test-columns\">\n   <section class=\"panel start\" id=\"test-panel\"><div class=\"section-label\">01 / START A GENUINE TEST</div><div class=\"heading\"><h2>Investigate a company</h2><span class=\"status-chip neutral\">Live browser test</span></div>\n    <form id=\"run-form\"><label for=\"url\">Company website</label><input id=\"url\" type=\"url\" list=\"allowed\" placeholder=\"https://1up-usa.com/\" autocomplete=\"off\" required><datalist id=\"allowed\"></datalist>\n     <div class=\"formline\"><div><label for=\"budget\">Pages to investigate</label><select id=\"budget\"><option value=\"3\">3 pages</option><option value=\"7\" selected>7 pages</option><option value=\"12\">12 pages</option></select></div>\n      <button id=\"run\" class=\"primary\" type=\"submit\">Run live investigation</button><button id=\"cancel\" class=\"outline\" type=\"button\" disabled>Stop after page</button></div></form>\n    <p id=\"run-hint\" class=\"fine\">Approved public company sites only. Robots and website access restrictions apply.</p>\n    <div class=\"statusline\"><span id=\"job-indicator\" class=\"dot\"></span><span id=\"job-status\" aria-live=\"polite\">No investigation started.</span></div>\n   </section>\n   <section class=\"panel system\"><div class=\"section-label\">HOW THIS LIVE TEST WORKS</div><h2>Cloudflare + your laptop</h2>\n    <div class=\"system-flow\"><div><strong>Team browser</strong><small>Choose company</small></div><span>→</span><div><strong>Cloudflare</strong><small>Manage live test</small></div><span>↔</span><div><strong>Local laptop</strong><small>Chromium + extraction</small></div></div>\n    <div class=\"info-line\">Actual pages are visited on the connected laptop. The team sees progress and the evidence-backed result. <strong>OS data is not connected.</strong></div>\n   </section>\n  </div>\n  <section class=\"panel jobs\" id=\"runs-panel\"><div class=\"section-label\">TEST HISTORY</div><div class=\"heading\"><h2>Recent real investigations</h2><span class=\"fine\">Choose a run to inspect findings or failures</span></div><div id=\"history\" class=\"history\"></div></section>\n  <div id=\"empty\" class=\"empty\" role=\"status\"><div class=\"empty-mark\">◎</div><strong>No completed website findings yet</strong><p>Run a test while the local bridge is connected. Results appear only when the scraper actually retrieves them.</p></div>\n  <section id=\"business\" hidden>\n   <section class=\"panel company-panel\"><div class=\"company-line\"><div class=\"company-icon\" aria-hidden=\"true\">▣</div><div><div class=\"section-label\">COMPANY INSIGHTS / FROM THE SELECTED LIVE RUN</div><h2 id=\"company-title\">Company</h2><span id=\"company-source\" class=\"fine\"></span></div><span id=\"role\" class=\"status-chip needs-review\">Role not independently verified</span></div><p id=\"executive-summary\" class=\"executive-summary\"></p></section>\n   <section class=\"panel\" id=\"coverage-panel\"><div class=\"heading\"><div><div class=\"section-label\">EXTRACTION COVERAGE</div><h2>What we could bring out</h2></div><span class=\"status-chip neutral\">Measured from this run</span></div>\n    <div id=\"coverage-summary\" class=\"coverage-grid\"></div><div id=\"metrics\" class=\"metrics\"></div>\n    <p class=\"fine\">Green means a website source was captured—not that its claim has been independently confirmed. Red means missing from this test, not nonexistent in the company.</p>\n   </section>\n   <section class=\"panel\" id=\"categories-panel\"><div class=\"heading\"><div><div class=\"section-label\">JS2 / SOURCE-EXTRACTED</div><h2>Product categories</h2></div><span id=\"categories-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"category-list\" class=\"category-grid\"></div></section>\n   <section class=\"panel\" id=\"products-panel\"><div class=\"heading\"><div><div class=\"section-label\">JS3 + JS4 / PRODUCT INTELLIGENCE</div><h2>Products, components &amp; materials</h2></div><span id=\"products-status\" class=\"status-chip neutral\">Not tested</span></div>\n    <p class=\"fine\">Open any product to inspect sourced specifications and component/material mentions. Component mentions are not confirmed BOM parts.</p>\n    <div id=\"product-tree\"></div></section>\n   <section class=\"panel\" id=\"taxonomy-panel\"><div class=\"heading\"><div><div class=\"section-label\">AI TAXONOMY ENRICHMENT</div><h2>Original taxonomy → AI working edition</h2></div><span id=\"taxonomy-status\" class=\"status-chip neutral\">Awaiting live run</span></div>\n    <p class=\"fine\">The original reference remains unchanged. Automatically proposed products, parts, materials and processes are labeled as AI hypotheses and need review.</p>\n    <div id=\"taxonomy-metrics\" class=\"metrics\"></div><div id=\"taxonomy-graph\" class=\"taxonomy-compare\"></div></section>\n   <section class=\"panel\" id=\"js-panel\"><div class=\"heading\"><div><div class=\"section-label\">JS1–JS10 / TRANSPARENT COVERAGE</div><h2>What we know, infer and couldn't find</h2></div><span class=\"status-chip neutral\">All ten sections</span></div>\n    <p class=\"fine\">Every section stays visible, including missing or blocked information. No section is marked verified without independent review.</p><div id=\"js-sections\" class=\"js-cards\"></div></section>\n   <div class=\"columns\">\n    <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">JS8 / APPLICATIONS</div><h2>Industries &amp; target markets</h2></div><span id=\"markets-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"target-markets\"></div></section>\n    <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">JS9 / COMPETITIVE INTELLIGENCE</div><h2>Key differentiators</h2></div><span id=\"differentiators-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"differentiators\"></div></section>\n   </div>\n   <div class=\"columns\">\n    <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">JS5 + JS6 / MANUFACTURING</div><h2>Manufacturing process intelligence</h2></div><span id=\"process-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"process\"></div></section>\n    <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">JS7 / SUPPLY CHAIN + OS</div><h2>Supplier intelligence &amp; OS</h2></div><span class=\"status-chip unavailable\">OS not connected</span></div>\n     <div id=\"supplier-insights\"></div><p class=\"missing\"><b>We couldn't bring out current OS records.</b> There is no authorized OS connection or JSON export.</p>\n     <details class=\"os-details\"><summary>Record an observation manually from OS</summary><form id=\"os-note-form\"><label for=\"os-product\">OS product</label><input id=\"os-product\" maxlength=\"120\">\n      <label for=\"os-part\">Part or component</label><input id=\"os-part\" maxlength=\"120\">\n      <label for=\"os-process\">Manufacturing process</label><input id=\"os-process\" maxlength=\"120\">\n      <label for=\"os-source\">Where observed in OS</label><input id=\"os-source\" maxlength=\"180\" placeholder=\"Company record or page reference\" required>\n      <button class=\"outline\" type=\"submit\">Add manual observation</button></form></details>\n     <div id=\"os-notes\"></div><p class=\"fine\">Manual observations remain only in this browser's memory and are not fetched from OS.</p></section>\n   </div>\n   <section class=\"panel\" id=\"sources-panel\"><div class=\"heading\"><div><div class=\"section-label\">JS10 / PROVENANCE</div><h2>Original website sources</h2></div><span id=\"sources-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"source-list\" class=\"source-grid\"></div></section>\n   <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">DATA EXPORT</div><h2>Candidate JSON for OS developers</h2></div><button id=\"download\" class=\"outline\" type=\"button\">Download candidate JSON</button></div>\n     <p class=\"fine\">Draft integration format only. No OS write, approved taxonomy mutation or verified manufacturing ownership.</p><details><summary>Inspect JSON preview</summary><pre id=\"json-preview\" class=\"code\"></pre></details></section>\n  </section>\n  <section id=\"technical\" hidden>\n   <section class=\"panel\"><div class=\"heading\"><div><div class=\"section-label\">TECHNICAL VIEW / REAL LOGS</div><h2>Page-by-page test execution</h2></div><span id=\"technical-status\" class=\"status-chip neutral\">Not tested</span></div><div id=\"tech-summary\"></div><div id=\"events\" class=\"timeline\"></div></section>\n   <section class=\"panel\"><div class=\"section-label\">ACTUAL EXTRACTION TRACE</div><h2>Visited source pages</h2><div class=\"scroller\"><table><thead><tr><th>Source URL</th><th>Result</th><th>Strategy</th><th>Text characters</th><th>Warnings / failures</th></tr></thead><tbody id=\"pages\"></tbody></table></div></section>\n   <section class=\"panel\"><div class=\"section-label\">GAPS &amp; LIMITATIONS</div><h2>What this run could not establish</h2><div id=\"limits\"></div></section>\n  </section>\n  <footer>Prototype evidence only. Real websites may block extraction. AI propositions are not verified manufacturing facts. OS integration is not connected.</footer>\n </main>\n</div>\n</body></html>";
export const uiCss="\n:root{--bg:#f4f6fb;--paper:#fff;--ink:#162238;--muted:#64748b;--line:#e2e8f0;--blue:#2559df;--blue-pale:#ecf2ff;--green:#15803d;--green-bg:#e8f8ed;--green-line:#bdeacb;--amber:#a65c09;--amber-bg:#fff4e2;--amber-line:#f8dbae;--red:#b42336;--red-bg:#fff0f1;--red-line:#f3c6cb;--radius:15px}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #ccd6e4;border-radius:9px;padding:10px 15px;background:#fff;color:#25344d;font-weight:700}button:hover:not(:disabled){filter:brightness(.97)}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #84a9ff;outline-offset:2px}button:disabled{opacity:.48;cursor:not-allowed}input,select{width:100%;border:1px solid #c8d3e1;background:#fff;color:#172b46;border-radius:9px;padding:11px 12px;min-height:43px}label{display:block;font-weight:700;font-size:12px;color:#44556b;margin:11px 0 6px}p{margin:8px 0 12px}h1,h2,h3,h4{line-height:1.27;letter-spacing:-.025em}h1{margin:10px 0;font-size:clamp(26px,2.8vw,36px)}h2{font-size:19px;margin:7px 0 15px}h3{font-size:15px;margin:7px 0}h4{font-size:13px;margin:4px 0 9px}a{color:#2656c7;overflow-wrap:anywhere}a:hover{text-decoration:underline}\n.top{height:72px;position:sticky;top:0;z-index:20;display:flex;align-items:center;justify-content:space-between;gap:16px;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);padding:12px 28px;backdrop-filter:blur(12px)}.identity{display:flex;align-items:center;gap:12px;min-width:0}.mark{display:grid;place-items:center;width:41px;height:41px;background:#e9efff;color:#3159c9;border-radius:11px;font-size:23px;font-weight:800}.brand{display:flex;flex-direction:column;line-height:1.28}.brand strong{font-size:18px;letter-spacing:-.04em}.brand small{color:var(--muted);font-size:10px}.top-actions{display:flex;align-items:center;gap:12px}.prototype-tag{color:#687991;font-size:10px;letter-spacing:.1em;font-weight:800}.pill,.status-chip{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 10px;line-height:1.35;font-size:11px;font-weight:750;white-space:nowrap;border:1px solid transparent}.pill:before,.status-chip:before{content:\"\";width:7px;height:7px;display:inline-block;flex:none;border-radius:50%;background:currentColor}.pill.online,.status-chip.available{color:var(--green);background:var(--green-bg);border-color:var(--green-line)}.pill.offline,.status-chip.unavailable{color:var(--red);background:var(--red-bg);border-color:var(--red-line)}.status-chip.needs-review{color:var(--amber);background:var(--amber-bg);border-color:var(--amber-line)}.status-chip.neutral{color:#4c6082;background:#ecf2fb;border-color:#d5e2f5}\n.app-shell{display:grid;grid-template-columns:228px minmax(0,1fr);max-width:1700px;margin:auto;min-height:calc(100vh - 72px)}.sidebar{position:sticky;top:72px;align-self:start;height:calc(100vh - 72px);overflow:auto;background:#f9fbff;border-right:1px solid var(--line);padding:27px 15px 22px}.sidebar-label{color:#8b98ab;font-size:10px;font-weight:850;letter-spacing:.12em;margin:5px 12px 15px}.nav-item{display:flex;align-items:center;width:100%;gap:13px;text-align:left;border:0;background:none;padding:11px 13px;border-radius:10px;font-size:13px;margin:2px 0;color:#536279}.nav-item.selected,.nav-item:hover{background:#e5edff;color:#2356ca}.nav-icon{font-size:16px;width:21px;text-align:center}.sidebar-divider{border-top:1px solid var(--line);margin:25px 6px 21px}.sidebar-status{display:flex;align-items:start;gap:10px;margin:15px 12px;color:#445670;font-size:12px}.sidebar-status b{display:block;font-size:11px}.sidebar-status small{color:#8793a5;display:block;font-size:10px}.sidebar-note{background:#eaf1ff;border:1px solid #dbe5fb;border-radius:12px;margin:29px 4px 0;padding:15px;font-size:11px;color:#37517b}.sidebar-note p{margin:5px 0 0}\n.workspace{padding:24px clamp(18px,3vw,38px) 46px;min-width:0;max-width:1460px;width:100%}.workspace-crumb{font-size:11px;color:#718198;margin-bottom:14px}.workspace-crumb span{padding:0 6px;color:#aab7c6}.hero{margin-bottom:18px}.hero-row{display:flex;align-items:flex-end;justify-content:space-between;gap:15px;flex-wrap:wrap}.hero p{color:#62728a;max-width:760px;font-size:13px}.eyebrow,.section-label{font-size:10px;font-weight:850;color:#5672b0;letter-spacing:.12em}.view-tabs{display:flex;gap:5px;background:#e9eef8;padding:4px;border:1px solid #dce5f1;border-radius:11px}.view-tabs button{border:0;background:transparent;font-size:12px;color:#61738c;padding:10px 15px}.view-tabs button.on{color:#1749bd;background:#fff;box-shadow:0 1px 8px #17295016}.status-legend{display:flex;align-items:center;flex-wrap:wrap;gap:14px 22px;padding:12px 15px;border:1px solid #e3eaf4;background:#fff;border-radius:10px;font-size:11px;color:#53657b}.status-legend strong{color:#1e344f}.status-legend span{display:inline-flex;gap:7px;align-items:center}.legend-dot{width:9px;height:9px;display:inline-block;border-radius:50%;flex:none;margin-top:4px}.legend-dot.green{background:#20a34a}.legend-dot.amber{background:#eba226}.legend-dot.red{background:#e64d59}\n.panel{background:var(--paper);border:1px solid #e2e8f3;border-radius:var(--radius);padding:20px 21px;box-shadow:0 6px 26px #22375608;margin:0 0 17px;min-width:0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:17px}.test-columns{grid-template-columns:minmax(0,1.22fr) minmax(280px,.78fr)}.heading{display:flex;align-items:flex-start;justify-content:space-between;gap:11px;flex-wrap:wrap}.heading h2{margin-bottom:12px}.fine{font-size:11px;color:#728198}.smallbadge{font-size:11px;color:#687a91;background:#f4f7fc;border-radius:99px;border:1px solid var(--line);padding:4px 9px}.formline{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.formline>div{width:165px}.primary{background:#235bdf;color:#fff;border-color:#235bdf;box-shadow:0 3px 10px #315cd229}.outline{background:#fff;color:#3a5577}.statusline{border:1px solid #dbe6f2;background:#f7faff;border-radius:9px;padding:11px 13px;display:flex;align-items:center;gap:9px;font-size:11px;margin-top:14px;color:#587088}.dot{height:8px;width:8px;border-radius:50%;display:inline-block;background:#9caec4}.dot.online{background:#14a44a;box-shadow:0 0 0 3px #34aa6030}.info-line{background:#f6f9ff;color:#607286;border:1px solid #e1e9f4;border-radius:9px;padding:11px 13px;font-size:11px}.system-flow{display:flex;gap:9px;align-items:center;margin:13px 0 14px}.system-flow>div{flex:1;background:#f7faff;border:1px solid #e5ebf4;border-radius:9px;padding:10px 8px;min-width:0}.system-flow strong{display:block;font-size:11px}.system-flow small{display:block;font-size:10px;color:#8b99aa}.system-flow>span{color:#7d9ac5}\n.history{display:flex;gap:9px;flex-wrap:wrap}.history button{min-width:165px;text-align:left;padding:11px 14px;background:#fafcff;border:1px solid #dce5f0;border-radius:9px}.history button.active{outline:2px solid #658ce9;outline-offset:0}.history button strong,.history button small{display:block}.history button small{color:#7a8a9d;font-size:10px}.history button.good{border-left:4px solid #2bb15b}.history button.bad{border-left:4px solid #e14e5d}.history button.working{border-left:4px solid #e5a63b}.empty{text-align:center;padding:40px 18px;background:#fff;border:1px dashed #cfd9e7;border-radius:14px;margin:17px 0;color:#607286}.empty strong{color:#304059;font-size:17px}.empty p{max-width:560px;margin:8px auto}.empty-mark{font-size:32px;color:#789bc7;margin-bottom:8px}\n.company-line{display:flex;align-items:center;gap:15px;flex-wrap:wrap}.company-line>div:nth-child(2){flex:1;min-width:0}.company-line h2{margin:2px 0 3px;font-size:23px}.company-icon{height:52px;width:52px;background:#e7efff;border-radius:14px;display:grid;place-items:center;color:#315ed1;font-size:25px}.executive-summary{background:#f8fafc;border-left:3px solid #a4bee9;color:#52657c;padding:13px 15px;border-radius:3px 9px 9px 3px;font-size:13px;margin:18px 0 0}\n.coverage-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:8px 0 15px}.coverage-tile{padding:15px;border-radius:11px;border:1px solid var(--line);min-height:98px}.coverage-tile strong{font-size:29px;display:block;line-height:1.2;margin:8px 0 2px}.coverage-tile span{font-size:11px;font-weight:750}.coverage-tile small{font-size:10px;display:block}.coverage-tile.green{background:var(--green-bg);border-color:var(--green-line);color:var(--green)}.coverage-tile.amber{background:var(--amber-bg);border-color:var(--amber-line);color:var(--amber)}.coverage-tile.red{background:var(--red-bg);border-color:var(--red-line);color:var(--red)}.coverage-tile.blue{background:#eaf2ff;border-color:#ceddfb;color:#2b59ba}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:12px 0}.metric{border:1px solid #e4e9f2;background:#f9fbfe;border-radius:10px;padding:12px}.metric strong{font-size:22px;color:#26405e;display:block}.metric span{color:#78889a;font-size:10px}\n.category-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.category-card{background:#f2fcf5;border:1px solid #d8efdf;border-radius:10px;padding:13px 14px;min-width:0}.category-card strong{display:block;color:#186b38;font-size:13px}.category-card small{color:#5f8a72;display:block;margin:4px 0 9px;font-size:10px}.category-card a{font-size:11px}\n.item{border:1px solid #e0e8f1;background:#fff;border-radius:11px;margin:9px 0;overflow:hidden}.item summary{cursor:pointer;font-weight:750;padding:13px 15px;display:flex;justify-content:space-between;gap:10px;list-style:none;background:#f9fbfd}.item[open] summary{background:#eff6ff;border-bottom:1px solid #e1e9f3}.item section{padding:15px}.item .cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.subpanel{background:#f8fbfe;border:1px solid #e6ecf3;border-radius:9px;padding:12px 13px;margin-bottom:11px}.subpanel h4{font-size:12px;color:#415e77;margin:0 0 9px}.subpanel p{font-size:12px;color:#576b7e}.quote{font-size:11px;color:#506a80;border-left:3px solid #80b9c8;padding:8px 10px;margin:9px 0;background:#fff;border-radius:3px}\n.chip{display:inline-block;margin:3px 5px 3px 0;border-radius:30px;padding:5px 10px;font-size:11px;background:#f1f5f9;color:#344558;border:1px solid #e0e8f0}.chip.review{background:var(--amber-bg);border-color:var(--amber-line);color:var(--amber)}.chip.ok{background:var(--green-bg);border-color:var(--green-line);color:var(--green)}\n.warn,.warning,.missing{padding:12px 14px;background:var(--red-bg);border:1px solid var(--red-line);color:#973245;border-radius:9px;font-size:12px}.review-box{background:var(--amber-bg);color:#85500b;border:1px solid var(--amber-line);border-radius:9px;padding:12px 14px;font-size:12px}.success-box{background:var(--green-bg);color:#17633a;border:1px solid var(--green-line);border-radius:9px;padding:12px 14px;font-size:12px}.ai-pending{background:#f0f5fd;border:1px dashed #bcd1ef;color:#536d9c;padding:16px;border-radius:10px}\n.taxonomy-compare{display:grid;grid-template-columns:1fr 1.3fr;gap:14px}.tax-side{background:#f8fafc;border:1px solid #e5ebf3;border-radius:11px;padding:15px;min-width:0}.tax-side h3{color:#30465e;font-size:14px}.tax-node{border:1px solid #dce6f0;background:#fff;border-radius:9px;margin:8px 0;padding:10px 11px;font-size:11px}.tax-node strong{display:block;font-size:12px}.tax-node small{display:block;color:#718498;margin:4px 0}.tax-node.original{border-left:4px solid #8393ab}.tax-node.observed{border-left:4px solid #28a65c}.tax-node.inferred{border-left:4px solid #e0a13c}.tax-children{border-left:1px dashed #bccbda;padding-left:13px;margin-left:12px}.tax-label{font-size:10px;font-weight:750;display:inline-block;padding:2px 8px;border-radius:99px;border:1px solid #d3dfee;background:#edf3fa;color:#516c8b;margin-left:7px}.tax-label.inferred{background:var(--amber-bg);border-color:var(--amber-line);color:var(--amber)}.tax-label.observed{background:var(--green-bg);border-color:var(--green-line);color:var(--green)}.tax-legend{display:flex;gap:13px;flex-wrap:wrap;font-size:10px;color:#687a90;margin:8px 0 12px}\n.js-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.js-row{display:grid;grid-template-columns:55px minmax(0,1fr);gap:10px;border:1px solid #e4eaf2;border-radius:10px;background:#fbfcfe;padding:12px}.js-row .js-id{font-weight:850;color:#325caa}.js-row strong{font-size:12px}.js-row p{font-size:11px;color:#697a8e;margin:7px 0 0}.js-row.missing{border-color:var(--red-line);background:#fff8f8;color:inherit}.js-row.review{border-color:var(--amber-line);background:#fffaf2}\n.timeline{background:#f7f9fc;max-height:360px;overflow:auto;border:1px solid #e1e8f1;border-radius:9px;padding:10px}.evt{font:11px/1.55 ui-monospace,Consolas,monospace;padding:8px 6px;border-bottom:1px solid #e7edf4;color:#586c84}.evt strong{color:#31445c}.evt.failure{background:#fff1f1;color:#ad3140}.evt.success{background:#f0faf3;color:#168045}.scroller{overflow:auto}table{border-collapse:collapse;min-width:730px;width:100%}th,td{text-align:left;padding:11px;border-bottom:1px solid #e5ebf2;font-size:11px;vertical-align:top}th{color:#718198;background:#f8fafc}td{color:#485e73}pre.code{font:11px/1.5 ui-monospace,Consolas,monospace;color:#d6e5ef;background:#14263d;padding:17px;border-radius:10px;max-height:350px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}\n.os-details{border:1px solid #e6eaf1;border-radius:9px;padding:12px;margin:12px 0}.source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.source-row{padding:11px;border:1px solid #e7edf4;border-radius:9px;background:#f8fbfe;font-size:11px;overflow-wrap:anywhere}.source-row small{display:block;color:#778a9b}.manual-note{padding:11px 0;border-bottom:1px solid #e8edf5;font-size:11px}.manual-note span{color:#63798b}footer{font-size:11px;color:#8491a2;padding:10px 0 20px}\n.loginwrap{min-height:calc(100vh - 72px);display:grid;place-items:center;padding:30px}.auth{background:#fff;border:1px solid #e4e9f2;box-shadow:0 20px 60px #20334a0f;max-width:510px;padding:36px;border-radius:18px}.auth h1{font-size:29px}.auth p{color:#627489}.auth .primary{width:100%;margin-top:14px}.error{color:#b42335;font-size:12px}\n[hidden]{display:none!important}\n@media(max-width:1140px){.app-shell{grid-template-columns:190px minmax(0,1fr)}.workspace{padding:21px}.coverage-grid{grid-template-columns:repeat(2,1fr)}.metrics{grid-template-columns:repeat(3,1fr)}.category-grid{grid-template-columns:repeat(2,1fr)}}\n@media(max-width:840px){.sidebar{position:static;height:auto;padding:10px;display:flex;flex-wrap:wrap;gap:4px}.app-shell{display:block}.sidebar-label,.sidebar-divider,.sidebar-status,.sidebar-note{display:none}.nav-item{width:auto;flex:1;justify-content:center;font-size:11px;min-width:100px}.workspace{padding:17px}.columns,.test-columns,.taxonomy-compare,.item .cols,.js-cards{grid-template-columns:1fr}.top{height:auto;min-height:65px}.prototype-tag{display:none}}\n@media(max-width:540px){.brand strong{font-size:15px}.brand small{display:none}.top{padding:10px 14px}.workspace{padding:14px}.panel{padding:16px}.status-legend{gap:8px}.coverage-grid,.category-grid,.metrics,.source-grid{grid-template-columns:1fr 1fr}.formline>div{width:100%}.formline button{flex:1}.status-chip{white-space:normal}.hero h1{font-size:27px}}\n\n#coverage-panel,#taxonomy-panel,#test-panel,#js-panel,#technical{scroll-margin-top:92px}\n";
export const uiJs="(()=>{\n'use strict';\nconst $=id=>document.getElementById(id);let key='',state=null,selected=null,selectedId=null,mode='business',poll=null,osNotes=[],lastView='';\nconst str=(x)=>String(x??'');\nconst el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=str(text);if(cls)n.className=cls;return n};\nconst put=(parent,tag,text,cls)=>{const n=el(tag,text,cls);parent.append(n);return n};\nconst href=(raw,label)=>{\n  const a=el('a',label||raw||'Original source');\n  try{const u=new URL(raw);if(u.protocol!=='https:'&&u.protocol!=='http:')throw Error();\n    a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';}\n  catch{a.removeAttribute('href');}\n  return a;\n};\nasync function api(path,{method='GET',body=null}={}){\n const r=await fetch(path,{method,cache:'no-store',\n   headers:{'Authorization':'Bearer '+key,...(body?{'Content-Type':'application/json'}:{})},\n   body:body?JSON.stringify(body):undefined});\n let j;try{j=await r.json()}catch{throw Error('Hosted service returned an invalid response')}\n if(!r.ok)throw Error(j.error||'Hosted service request failed');\n return j;\n}\nfunction switchMode(next){mode=next;const b=next==='business';\n $('mode-business').classList.toggle('on',b);$('mode-technical').classList.toggle('on',!b);\n $('mode-business').setAttribute('aria-pressed',String(b));\n $('mode-technical').setAttribute('aria-pressed',String(!b));updateView();}\n$('mode-business').addEventListener('click',()=>switchMode('business'));\n$('mode-technical').addEventListener('click',()=>switchMode('technical'));\nfunction setHint(t){$('run-hint').textContent=t}\nfunction logStatus(txt){$('job-status').textContent=txt}\nfunction metric(r,value,label){const x=put(r,'div',undefined,'metric');put(x,'strong',value);put(x,'span',label)}\nfunction source(parent,entry){\n if(entry?.evidence?.quote)put(parent,'div','Published excerpt: \"'+entry.evidence.quote+'\"','quote');\n const url=entry?.evidence?.sourceUrl||entry?.sourceUrl;\n if(url)parent.append(href(url,'Open original page'));\n}\nfunction emptyMsg(root,text){put(root,'p',text,'fine')}\nfunction chip(id,kind,label){const x=$(id);x.className='status-chip '+kind;x.textContent=label;}\nfunction noEvidence(root,description){put(root,'div',\"We couldn't bring this out. \"+description,'missing');}\nfunction review(root,description){put(root,'div','Needs human review. '+description,'review-box');}\nfunction available(root,description){put(root,'div',description,'success-box');}\nfunction counter(root,value,label,tone){const n=put(root,'div',undefined,'coverage-tile '+tone);put(n,'span',label);put(n,'strong',value);put(n,'small',tone==='green'?'Extracted with source':tone==='amber'?'Unverified / AI proposal':tone==='red'?'Not found in this test':'Website evidence');}\nfunction tag(root,title,kind='review'){put(root,'span',title,'chip '+kind);}\nfunction sourceLink(parent,url,label){if(url)parent.append(href(url,label||'Open website source'));}\nfunction preliminarySections(run){\n const r=run?.result||{},pi=r.productIntelligence||{},products=pi.products||[],pages=r.acquisition?.pages||[];\n const observedMaterials=products.reduce((n,p)=>n+(p.materials?.length||0),0);\n const has=c=>pages.some(p=>p.status==='completed'||p.status==='partial');\n const rows=[\n ['JS1','Company overview & identity',r.company?.name?'observed_candidate':'unknown',\n  r.company?.name?'Company website and identity retrieved; company role is a candidate.':'No usable company identity retrieved.'],\n ['JS2','Product categories',pi.categories?.length?'observed_candidate':'unknown',\n  pi.categories?.length+' website category candidates.'],\n ['JS3','Product & component hierarchy',products.length?'observed_candidate':'unknown',\n  products.length+' product candidates. Complete bill of materials not verified.'],\n ['JS4','Materials',observedMaterials?'observed_candidate':'unknown',\n  observedMaterials+' explicit material mentions.'],\n ['JS5','Manufacturing process requirements',r.manufacturing?.claims?.some(c=>c.section==='JS5')?'source_claim_unverified':'unknown',\n  'No verified product-specific manufacturing process requirements.'],\n ['JS6','In-house manufacturing capabilities',r.manufacturing?.claims?.some(c=>c.section==='JS6')?'source_claim_unverified':'unknown',\n  'No confirmed company-performed manufacturing operations.'],\n ['JS7','Supply chain intelligence','unknown','Specific supplier relationships and actual purchase requirements are not established.'],\n ['JS8','Industries & target markets','unknown','No independently reviewed target-market links in this report.'],\n ['JS9','Differentiators','unknown','No independently reviewed differentiators in this report.'],\n ['JS10','Evidence & confidence',has()?'observed_candidate':'unknown',\n  pages.length+' source page records; source traceability is not independent accuracy.']\n ];\n return rows.map(([code,name,status,summary])=>({code,name,status,summary,verified:false}));\n}\nfunction getSections(run){\n const sections=run?.enrichment?.sections;\n return Array.isArray(sections)&&sections.length===10?sections:preliminarySections(run);\n}\nfunction sectionTone(status){\n if(status==='observed_candidate')return 'available';\n if(status==='ai_inferred'||status==='source_claim_unverified')return 'needs-review';\n return 'unavailable';\n}\nfunction statusText(status){\n if(status==='observed_candidate')return 'Extracted';\n if(status==='ai_inferred')return 'AI inferred · review';\n if(status==='source_claim_unverified')return 'Claim · review';\n return \"Couldn't bring this out\";\n}\nfunction goTo(id,view){\n if(view)switchMode(view);\n const target=$(id);\n if(target)requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'}));\n}\n$('nav-tests').addEventListener('click',()=>goTo('test-panel'));\n$('nav-results').addEventListener('click',()=>goTo('coverage-panel','business'));\n$('nav-taxonomy').addEventListener('click',()=>goTo('taxonomy-panel','business'));\n$('nav-technical').addEventListener('click',()=>goTo('technical','technical'));\n\nfunction drawTree(r){\n const root=$('product-tree');root.replaceChildren();\n const products=r?.productIntelligence?.products||[],categories=r?.productIntelligence?.categories||[];\n const byId=new Map(categories.map(c=>[c.id,c.name]));\n chip('products-status',products.length?'available':'unavailable',\n  products.length?'Products extracted · unverified':\"Couldn't bring this out\");\n if(!products.length){\n  noEvidence(root,'No defensible product records were found on the pages visited. The company may still sell products.');\n  return;\n }\n for(const [i,p] of products.slice(0,55).entries()){\n  const details=put(root,'details',undefined,'item');if(i===0)details.open=true;\n  const summary=put(details,'summary');\n  put(summary,'span',p.name+(p.sku?' · '+p.sku:''));\n  put(summary,'span','Website candidate · review','status-chip needs-review');\n  const body=put(details,'section');\n  put(body,'p','Source-extracted product candidate. The company may manufacture, resell or distribute it; ownership is not established.','fine');\n  sourceLink(body,p.sourceUrl,'Open product webpage');\n  const cols=put(body,'div',undefined,'cols');\n  const left=put(cols,'div'),right=put(cols,'div');\n  const category=put(left,'div',undefined,'subpanel');\n  put(category,'h4','Product category');\n  const names=(p.categories||[]).map(id=>byId.get(id)).filter(Boolean);\n  if(names.length)names.forEach(x=>tag(category,x,'ok'));\n  else noEvidence(category,'The relationship between this product and a category is unresolved.');\n  const spec=put(left,'div',undefined,'subpanel');\n  put(spec,'h4','Published specifications');\n  if(!p.specs?.length)noEvidence(spec,'No technical specifications were extracted for this product.');\n  for(const x of p.specs||[]){\n   put(spec,'div',x.name+': '+x.value,'success-box');source(spec,x);\n  }\n  const parts=put(right,'div',undefined,'subpanel');\n  put(parts,'h4','Explicit component mentions');\n  if(!p.components?.length)noEvidence(parts,'We could not establish any sourced component relationships.');\n  for(const x of p.components||[]){\n   tag(parts,x.value,'ok');source(parts,x);\n  }\n  const mat=put(right,'div',undefined,'subpanel');\n  put(mat,'h4','Explicit material mentions');\n  if(!p.materials?.length)noEvidence(mat,'No published product-specific material claims were retrieved.');\n  for(const x of p.materials||[]){\n   tag(mat,x.value,'ok');source(mat,x);\n  }\n  review(body,'Component mentions do not establish a verified bill of materials. Product-specific processes and in-house manufacturing remain unverified.');\n }\n}\n\nfunction drawProcesses(r,run){\n const root=$('process');root.replaceChildren();\n const claims=r?.manufacturing?.claims||[];\n const aiItems=run?.enrichment?.proposals?.items||[];\n const aiProcesses=aiItems.flatMap(item=>(item.processes||[]).map(x=>({...x,productName:item.productName})));\n if(claims.length||aiProcesses.length)chip('process-status','needs-review','Needs human review');\n else chip('process-status','unavailable',\"Couldn't bring this out\");\n if(!claims.length&&!aiProcesses.length){\n  noEvidence(root,'No supported manufacturing-process relationships were established from available website evidence.');\n }else{\n  if(aiProcesses.length){\n   review(root,'The following are AI-generated POSSIBLE manufacturing requirements, not verified production steps or company capabilities.');\n   for(const x of aiProcesses.slice(0,12)){\n    const item=put(root,'div',undefined,'subpanel');\n    tag(item,x.name,'review');\n    put(item,'p','Potentially relevant to '+x.productName+' / '+x.part+'. '+(x.reason||''),'fine');\n   }\n  }\n  if(claims.length){\n   review(root,'These source-quoted statements require review; JS5 product process relevance is not JS6 actual in-house capability.');\n   for(const x of claims.slice(0,10)){\n    const details=put(root,'details',undefined,'item');\n    put(details,'summary',(x.section==='JS5'?'JS5 · Product process claim':'JS6 · In-house capability claim')+' · '+x.claim.slice(0,75));\n    const box=put(details,'section');\n    put(box,'p',x.claim);\n    source(box,{evidence:x.source});\n   }\n  }\n }\n if(!claims.some(x=>x.section==='JS6')){\n  noEvidence(root,'We could not verify which manufacturing processes this company actually performs in-house (JS6).');\n }\n}\n\nfunction drawTaxonomy(run){\n const status=$('taxonomy-status'),root=$('taxonomy-graph'),metrics=$('taxonomy-metrics');\n root.replaceChildren();metrics.replaceChildren();\n const a=run?.enrichment,reference=run?.result?.taxonomyReference;\n chip('taxonomy-status',a?.status==='completed'?'needs-review':a?.status==='queued'?'neutral':a?'unavailable':'neutral',\n   a?.status==='completed'?'AI proposal · review':a?.status==='queued'?'AI generating…':a?'Couldn\\'t bring this out':'Not started');\n if(!a||a.status==='queued'){\n  // Status is conveyed by the color-coded badge above.\n  put(root,'div',a?.status==='queued'?\n   'Real website research finished. Workers AI is proposing parts, materials, processes and taxonomy changes.':\n   'No AI working edition yet.','ai-pending');return;\n }\n // AI status has already been mapped to a review/missing badge.\n const tax=a.workingTaxonomy;\n if(!tax){\n  put(root,'p','No working edition was produced: '+(a.reason||'inference not available'),'warn');\n  return;\n }\n const ref=tax.reference||{};\n metric(metrics,ref.totalNodes||0,'Original master nodes (laptop)');\n metric(metrics,ref.selectedOriginalAnchors||0,'Original anchors sampled');\n metric(metrics,tax.newWorkingNodes||0,'Working nodes added');\n metric(metrics,tax.aiGeneratedNodes||0,'AI hypothesis nodes');\n metric(metrics,0,'Canonical nodes overwritten');\n const left=put(root,'div',undefined,'tax-side');\n put(left,'h3','Original taxonomy · unchanged');\n if(ref.status!=='installed')put(left,'p','No original taxonomy was installed on the laptop for this run.','warn');\n else{\n  put(left,'p','Original reference contains '+ref.totalNodes+' nodes. Only relevant selected nodes are displayed.','fine');\n  const originals=(tax.nodes||[]).filter(x=>x.kind==='original');\n  for(const n of originals.slice(0,14)){\n   const e=put(left,'div',undefined,'tax-node original');\n   put(e,'strong',n.label);\n   put(e,'small',n.code+' · '+n.path);\n  }\n  if(originals.length>14)put(left,'p','+ '+(originals.length-14)+' more selected original nodes.','fine');\n }\n const right=put(root,'div',undefined,'tax-side');\n put(right,'h3','AI + website working taxonomy · automatic proposal');\n const legend=put(right,'div',undefined,'tax-legend');\n put(legend,'span','Green = website candidate');put(legend,'span','Amber = AI hypothesis');\n put(right,'p','Added here without approval. None of these nodes changes the original taxonomy or claims OS integration.','fine');\n const nodes=(tax.nodes||[]).filter(x=>x.kind!=='original'),children=new Map();\n for(const n of nodes){\n  const key=n.parentId||'root';if(!children.has(key))children.set(key,[]);\n  children.get(key).push(n);\n }\n const visited=new Set();\n function tree(node,parent,depth){\n  if(visited.has(node.id)||depth>4)return;visited.add(node.id);\n  const ai=node.addedByAi===true;\n  const block=put(parent,'div',undefined,'tax-node '+(ai?'inferred':'observed'));\n  const title=put(block,'strong',node.label);\n  put(title,'span',ai?'AI proposal':'Website candidate','tax-label '+(ai?'inferred':'observed'));\n  put(block,'small',node.kind+(node.reason?' · '+node.reason:''));\n  if(node.sourceUrl)block.append(href(node.sourceUrl,'Source context'));\n  const kids=(children.get(node.id)||[]).slice(0,12);\n  if(kids.length){const inner=put(parent,'div',undefined,'tax-children');\n    for(const kid of kids)tree(kid,inner,depth+1);}\n }\n const roots=nodes.filter(n=>!n.parentId||String(n.parentId).startsWith('original:'));\n for(const n of roots.slice(0,22))tree(n,right,0);\n if(!nodes.length)put(right,'p','No proposed taxonomy nodes were created from this investigation.','warn');\n}\nfunction drawJsSections(run){\n const root=$('js-sections');root.replaceChildren();\n const sections=getSections(run);\n const pending=run?.enrichment?.status==='queued';\n if(pending)put(root,'p','Cloudflare Workers AI is still generating proposals. Website-extracted coverage is shown below until inference completes.','ai-pending');\n for(const sec of sections){\n  const tone=sectionTone(sec.status);\n  const row=put(root,'div',undefined,'js-row '+(tone==='unavailable'?'missing':tone==='needs-review'?'review':''));\n  put(row,'span',sec.code,'js-id');\n  const body=put(row,'div');\n  put(body,'strong',sec.name);\n  put(body,'span',statusText(sec.status),'status-chip '+tone);\n  if(tone==='unavailable'){\n   put(body,'p',\"We couldn't bring this out. \"+sec.summary);\n  }else if(tone==='needs-review'){\n   put(body,'p','Needs human review. '+sec.summary);\n  }else put(body,'p','Website extracted (not independently verified). '+sec.summary);\n }\n}\nfunction drawCategories(r){\n const root=$('category-list');root.replaceChildren();\n const cats=r?.productIntelligence?.categories||[],products=r?.productIntelligence?.products||[];\n chip('categories-status',cats.length?'available':'unavailable',\n  cats.length?'Categories extracted · review':\"Couldn't bring this out\");\n if(!cats.length){\n  noEvidence(root,'No category names could be supported by pages visited during this investigation.');return;\n }\n for(const c of cats.slice(0,45)){\n  const tile=put(root,'div',undefined,'category-card');\n  put(tile,'strong',c.name);\n  const linked=products.filter(p=>(p.categories||[]).includes(c.id));\n  put(tile,'small',linked.length?linked.length+' linked product candidate(s)':'Category found · no product relationship established');\n  for(const p of linked.slice(0,4))tag(tile,p.name,'ok');\n  if(linked.length>4)tag(tile,'+'+(linked.length-4)+' more','ok');\n  if(c.sourceUrl)put(tile,'div').append(href(c.sourceUrl,'Open source category'));\n }\n}\nfunction drawMarketsDifferentiatorsSupply(run){\n const p=run?.enrichment?.proposals||{};\n const targets=$('target-markets'),diffs=$('differentiators'),supplier=$('supplier-insights');\n targets.replaceChildren();diffs.replaceChildren();supplier.replaceChildren();\n const markets=p.marketHypotheses||[],differentiators=p.differentiatorHypotheses||[];\n const supplierHypotheses=p.supplierOpportunityHypotheses||[];\n chip('markets-status',markets.length?'needs-review':'unavailable',\n  markets.length?'AI inference · review':\"Couldn't bring this out\");\n chip('differentiators-status',differentiators.length?'needs-review':'unavailable',\n  differentiators.length?'AI inference · review':\"Couldn't bring this out\");\n if(markets.length){\n  review(targets,'These market/application links are possible, not independently verified.');\n  markets.forEach(x=>tag(targets,x,'review'));\n }else noEvidence(targets,'Target markets were not established from this run.');\n if(differentiators.length){\n  review(diffs,'These differentiators are AI suggestions, not verified competitive advantages.');\n  const ul=put(diffs,'ul');\n  for(const x of differentiators)put(ul,'li',x);\n }else noEvidence(diffs,'No sufficiently grounded differentiators were established in the available evidence.');\n if(supplierHypotheses.length){\n  review(supplier,'Possible supplier opportunities—not confirmed sourcing requirements or purchase orders.');\n  supplierHypotheses.forEach(x=>tag(supplier,x,'review'));\n }else noEvidence(supplier,'Actual supplier relationships, outsourcing details and sourcing requirements were not established.');\n}\nfunction drawSources(r){\n const root=$('source-list');root.replaceChildren();\n const pages=r?.acquisition?.pages||[];\n const found=pages.filter(x=>x.url&&(x.status==='completed'||x.status==='partial'));\n chip('sources-status',found.length?'available':'unavailable',\n  found.length?found.length+' page source(s)':'No usable pages');\n if(!pages.length){noEvidence(root,'No website page records were returned for this investigation.');return;}\n for(const p of pages){\n  const item=put(root,'div',undefined,'source-row');\n  sourceLink(item,p.url,p.title||p.url||'Page unavailable');\n  const ok=p.status==='completed'||p.status==='partial';\n  put(item,'small',(p.status||'unknown')+' · '+(p.strategy||'unknown strategy'));\n  if(!ok&&p.warning?.length)put(item,'div',p.warning.join('; '),'missing');\n }\n}\n\nfunction drawBusiness(run){\n const r=run?.result,$biz=$('business');\n $biz.hidden=!r;\n if(!r)return;\n const pi=r.productIntelligence||{},acu=r.acquisition||{},products=pi.products||[],categories=pi.categories||[],pages=acu.pages||[];\n const specs=products.reduce((n,p)=>n+(p.specs?.length||0),0);\n const components=products.reduce((n,p)=>n+(p.components?.length||0),0);\n const materials=products.reduce((n,p)=>n+(p.materials?.length||0),0);\n const usable=pages.filter(p=>['completed','partial'].includes(p.status)).length;\n const stats=$('metrics');stats.replaceChildren();\n metric(stats,acu.pagesVisited||pages.length,'Pages attempted');\n metric(stats,usable,'Usable pages');\n metric(stats,categories.length,'Categories found');\n metric(stats,products.length,'Product candidates');\n metric(stats,specs+components+materials,'Specifications / mentions');\n const company=r.company||{};\n $('company-title').textContent=company.name||'Company information unavailable';\n chip('role','needs-review','Company role: '+(company.roleCandidate||'unknown')+' · review');\n const src=$('company-source');src.replaceChildren();sourceLink(src,company.url,'Open company website');\n $('executive-summary').textContent=(acu.pagesVisited||pages.length)>0?\n  'In this website investigation we attempted '+(acu.pagesVisited||pages.length)+' pages and retrieved '+\n  products.length+' product candidate(s), '+categories.length+' category candidate(s), '+specs+\n  ' specifications, '+components+' component mentions and '+materials+' material claims. The results are limited to the sampled pages.':\n  \"We couldn't bring out usable company intelligence because the investigation did not return enough page evidence.\";\n const sections=getSections(run), counts={available:0,'needs-review':0,unavailable:0};\n for(const s of sections)counts[sectionTone(s.status)]++;\n const over=$('coverage-summary');over.replaceChildren();\n counter(over,counts.available,'Extracted sections','green');\n counter(over,counts['needs-review'],'Needs human review','amber');\n counter(over,counts.unavailable,\"Couldn't bring out\",'red');\n counter(over,usable,'Usable source pages','blue');\n drawCategories(r);drawTree(r);drawProcesses(r,run);drawTaxonomy(run);\n drawJsSections(run);drawMarketsDifferentiatorsSupply(run);drawSources(r);\n const small={...r,productIntelligence:{...pi,products:products.slice(0,2)},\n  enrichmentStatus:run?.enrichment?.status||'not_started',\n  aiWorkingTaxonomySummary:run?.enrichment?.workingTaxonomy?{\n   newNodes:run.enrichment.workingTaxonomy.newWorkingNodes,\n   inferredNodes:run.enrichment.workingTaxonomy.aiGeneratedNodes,\n   masterModified:false}:null,\n  _preview:'Two product candidates shown; use Download for the actual bounded full JSON.'};\n $('json-preview').textContent=JSON.stringify(small,null,2).slice(0,11000);\n}\n\nfunction drawTechnical(run){\n const e=$('events'),p=$('pages'),lim=$('limits'),top=$('tech-summary');\n e.replaceChildren();p.replaceChildren();lim.replaceChildren();top.replaceChildren();\n if(!run){chip('technical-status','neutral','Not started');emptyMsg(top,'No live website investigation has started.');return;}\n chip('technical-status',run.status==='failed'?'unavailable':run.status==='completed'?'available':'needs-review',\n   run.status==='failed'?'Run failed':run.status==='completed'?'Run completed':'Investigation running');\n put(top,'p','Run: '+run.url+' · '+run.status+' · '+(run.result?.technical?.strategy||'auto')+\n  ' / '+(run.result?.technical?.browser||'local headless browser'));\n if(run.error)noEvidence(top,'Run failed: '+run.error);\n for(const x of run.events||[]){\n  const value=String(x.status||'unknown');\n  const isBad=/fail|block|timeout|denied|error|unavailable|403|429/i.test(value+' '+(x.reason||''));\n  const isGood=/completed|success|usable|matched/i.test(value);\n  const line=put(e,'div',undefined,'evt '+(isBad?'failure':isGood?'success':''));\n  put(line,'strong',(isBad?'FAILED · ':isGood?'OK · ':'EVENT · ')+value+' ');\n  line.append(document.createTextNode((x.strategy?'['+x.strategy+'] ':'')+\n    (x.url||'')+(x.reason?' — '+x.reason:'')));\n }\n if(!run.events?.length)emptyMsg(e,'No page events received yet. This does not mean the site failed.');\n const pages=run.result?.acquisition?.pages||[];\n for(const page of pages){\n  const tr=put(p,'tr'),url=put(tr,'td');\n  sourceLink(url,page.url,page.url);\n  const ok=['completed','partial'].includes(page.status);\n  const result=put(tr,'td');\n  put(result,'span',ok?'Extracted':page.status||'Unusable','status-chip '+(ok?'available':'unavailable'));\n  put(tr,'td',page.strategy||'—');put(tr,'td',Number(page.textChars||0).toLocaleString());\n  const warnings=put(tr,'td');\n  if(page.warning?.length)put(warnings,'span',page.warning.join('; '),'missing');\n  else put(warnings,'span',ok?'No warnings recorded':'No usable text recorded','fine');\n }\n if(!pages.length)emptyMsg(lim,run.status==='running'||run.status==='queued'?\n   'Research is in progress; page records are published after completion.':\n   \"We couldn't bring out any usable page records from this run.\");\n for(const item of run.result?.limitations||[])put(lim,'p',item,'fine');\n if(run.enrichment?.status==='failed')noEvidence(lim,'Cloudflare AI enrichment failed: '+(run.enrichment.reason||'Unknown model error'));\n if(run.error)noEvidence(lim,'Investigation failed: '+run.error);\n}\n\nfunction updateView(){\n const hasRun=selected!==null,hasResults=!!selected?.result;\n $('business').hidden=mode!=='business'||!hasResults;\n $('technical').hidden=mode!=='technical'||!hasRun;\n const empty=$('empty');empty.hidden=mode==='technical'&&hasRun||hasResults;\n if(!hasResults){\n  empty.replaceChildren();\n  const failed=selected?.status==='failed',running=selected?.status==='running'||selected?.status==='queued';\n  const label=failed?\"We couldn't bring this out from this run.\":running?\n    'A real website investigation is running.':'No real results have been fetched yet.';\n  put(empty,'div',failed?'×':running?'◉':'◎','empty-mark');\n  put(empty,'strong',label);\n  put(empty,'p',failed?(selected.error||'The website may have blocked access or the laptop could not complete the test. Switch to Technical View to inspect errors.'):\n    running?'The connected laptop is acquiring pages. Open Technical View for live events; Product Insights will show findings when extraction finishes.':\n    'Start an approved website test while the laptop bridge is online. This page does not load example or mock data.');\n }\n if(mode==='business')drawBusiness(selected);\n else if(mode==='technical')drawTechnical(selected);\n}\n\nfunction renderState(){\n const online=state?.laptop?.online===true;\n $('connection').textContent=online?'Laptop browser connected':'Laptop disconnected';\n $('connection').className='pill '+(online?'online':'offline');\n $('job-indicator').className='dot'+(online?' online':'');\n const runs=state?.runs||[],active=runs.find(x=>x.id===state.activeRunId);\n $('run').disabled=!online||!!active;\n $('cancel').disabled=!active;\n logStatus(active?'Real investigation: '+active.url+' · '+active.status:\n   online?'Connected. Choose a company to run a genuine test.':\n    'Laptop bridge is offline. Starting new research is unavailable.');\n const history=$('history');history.replaceChildren();\n if(!runs.length)emptyMsg(history,'No investigations have been run yet. No preloaded sample results.');\n for(const x of runs){\n  const tone=x.status==='failed'?'bad':x.status==='completed'?'good':'working';\n  const b=put(history,'button',undefined,(x.id===selectedId?'active ':'')+tone);\n  b.type='button';\n  put(b,'strong',x.url.replace(/^https:\\/\\//,'').slice(0,51));\n  put(b,'small',(x.status==='failed'?'Failed':x.status==='completed'?'Completed':'Live / '+x.status)+\n   ' · '+new Date(x.createdAt).toLocaleTimeString());\n  if(x.aiStatus==='queued')put(b,'small','Cloudflare AI: generating working taxonomy');\n  if(x.aiStatus==='failed')put(b,'small','Cloudflare AI enrichment failed');\n  if(x.aiStatus==='completed')put(b,'small',(x.taxonomyNodesAdded||0)+' taxonomy working nodes added');\n  b.addEventListener('click',()=>{selectedId=x.id;loadSelected().catch(showError)});\n }\n if(!selectedId&&runs.length)selectedId=runs[0].id;\n}\n\nfunction showError(e){setHint('Request error: '+e.message)}\nasync function loadSelected(){\n if(!selectedId){if(selected!==null){selected=null;lastView='';updateView();}return;}\n const fresh=await api('/api/runs/'+encodeURIComponent(selectedId));\n // Preserve expanded products, taxonomy branches, scrolling and JSON details while polling.\n // Re-render only when the actual job status, evidence events or AI proposal state changes.\n const stamp=JSON.stringify([\n  fresh.id,fresh.status,fresh.aiStatus,fresh.error,\n  fresh.events?.length,\n  fresh.events?.at(-1)?.time,fresh.events?.at(-1)?.status,\n  !!fresh.result,fresh.enrichment?.status,\n  fresh.enrichment?.workingTaxonomy?.newWorkingNodes\n ]);\n selected=fresh;\n if(stamp!==lastView){lastView=stamp;updateView();}\n}\nasync function tick(){\n try{state=await api('/api/state');renderState();await loadSelected();}\n catch(e){$('connection').textContent='Connection failed';showError(e)}\n}\n$('login-form').addEventListener('submit',async e=>{\n e.preventDefault();key=$('team-key').value.trim();$('team-key').value='';\n try{\n   const session=await api('/api/session');\n   $('login').hidden=true;$('app').hidden=false;\n   const datalist=$('allowed');datalist.replaceChildren();\n   for(const h of session.allowedHosts||[]){\n     const op=el('option');op.value='https://'+h+'/';datalist.append(op);\n   }\n   const first=session.allowedHosts?.[0];if(first)$('url').value='https://'+first+'/';\n   await tick();poll=setInterval(()=>tick().catch(showError),2500);\n }catch(e){key='';$('login-message').textContent='Authentication failed: '+e.message}\n});\n$('run-form').addEventListener('submit',async e=>{\n e.preventDefault();\n const button=$('run');button.disabled=true;setHint('Submitting approved website to the connected laptop...');\n try{const x=await api('/api/runs',{method:'POST',body:{\n   url:$('url').value.trim(),maxPages:Number($('budget').value)}});\n   selectedId=x.run.id;setHint('Queued a real website run. The laptop will execute it; no content is fabricated.');\n   await tick();\n }catch(e){showError(e)}finally{button.disabled=false}\n});\n$('cancel').addEventListener('click',async()=>{\n try{await api('/api/cancel',{method:'POST'});setHint('Stop requested; the local scraper will finish its current page.');}\n catch(e){showError(e)}\n});\n$('download').addEventListener('click',()=>{\n if(!selected?.result)return;\n const file={schemaVersion:'pi-live-lab-os-review-candidate/v1',\n   osWritePerformed:false,reviewStatus:'unreviewed',\n   company:selected.result.company,\n   proposedProducts:selected.result.productIntelligence,\n   manufacturing:selected.result.manufacturing,\n   aiWorkingEdition:selected.enrichment?.workingTaxonomy||null,\n   aiSections:selected.enrichment?.sections||[],\n   limitations:selected.result.limitations};\n const blob=new Blob([JSON.stringify(file,null,2)],{type:'application/json'});\n const u=URL.createObjectURL(blob),a=document.createElement('a');\n a.href=u;a.download='product-insights-source-candidates.json';a.click();\n setTimeout(()=>URL.revokeObjectURL(u),1000);\n});\n$('os-note-form').addEventListener('submit',e=>{\n e.preventDefault();const product=$('os-product').value.trim(),source=$('os-source').value.trim();\n if(!source||(!product&&!$('os-part').value&&!$('os-process').value))return;\n osNotes.push({product,part:$('os-part').value.trim(),process:$('os-process').value.trim(),source});\n $('os-note-form').reset();const root=$('os-notes');root.replaceChildren();\n for(const x of osNotes.slice(-8)){\n   const n=put(root,'div',undefined,'manual-note');\n   put(n,'strong',x.product||'(unlinked record)');put(n,'span',\n     ' · part: '+(x.part||'unknown')+' · process: '+(x.process||'unknown'));\n   put(n,'div','Manually observed in OS: '+x.source,'fine');\n }\n});\n})();\n";
